  }
}

/**
 * 版本化管理（记录 Schema 变化）
 */
async function logMigration(table, operations, version = 'latest') {
  try {
    const migrationTable = process.env.MIGRATION_LOG_TABLE || 'schema_migrations';

    // 插入迁移记录
    await pool.query(
